#include <bits/stdc++.h>
using namespace std;
int main(int argc,char**argv){int q=argc>1?atoi(argv[1]):4;vector<string> ss;for(int i=0;i<q;i++)for(int j=0;j<q;j++){string s;s+=char('0'+i);s+=char('0'+j);s+=char('0'+j);s+=char('0'+i);ss.push_back(s);}int n=ss.size();vector<vector<int>> c(n,vector<int>(n));for(int i=0;i<n;i++)for(int j=0;j<n;j++){int z=0;for(int k=3;k>=0;k--)if(ss[i].substr(4-k)==ss[j].substr(0,k)){z=k;break;}c[i][j]=4-z;}const int I=1000000;int N=1<<n;vector<int> dp((size_t)N*n,I);vector<unsigned long long> ways((size_t)N*n);dp[n]=0;ways[n]=1;for(int mask=1;mask<N;mask+=2){for(int j=0;j<n;j++)if(mask&(1<<j)){size_t id=(size_t)mask*n+j;if(dp[id]==I)continue;for(int k=1;k<n;k++)if(!(mask&(1<<k))){size_t ni=(size_t)(mask|(1<<k))*n+k;int val=dp[id]+c[j][k];if(val<dp[ni])dp[ni]=val,ways[ni]=ways[id];else if(val==dp[ni])ways[ni]+=ways[id];}}}int best=I;unsigned long long count=0;for(int j=0;j<n;j++){int v=dp[(size_t)(N-1)*n+j]+c[j][0];if(v<best){best=v;count=ways[(size_t)(N-1)*n+j];}else if(v==best)count+=ways[(size_t)(N-1)*n+j];}cout<<"q="<<q<<" n="<<n<<" min="<<best<<" optimal target orders="<<count<<"\n";}
